// NOVEL — not generated by CLI Printing Press.

package sqlguard

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"path/filepath"
	"strings"
	"testing"

	"modernc.org/sqlite"
	sqlite3 "modernc.org/sqlite/lib"
)

// openCapFixture opens a throwaway SQLite file. A file rather than :memory:
// because the limit is read back off the connection instance, which a shared
// in-memory DSN makes ambiguous.
func openCapFixture(t *testing.T) *sql.DB {
	t.Helper()
	path := filepath.Join(t.TempDir(), "cap.db")
	db, err := sql.Open("sqlite", "file:"+path)
	if err != nil {
		t.Fatalf("opening fixture: %v", err)
	}
	t.Cleanup(func() { _ = db.Close() })
	if err := db.PingContext(context.Background()); err != nil {
		t.Fatalf("pinging fixture: %v", err)
	}
	return db
}

// TestCapConnSetsTheLimitOnTheConnectionItReturns is the whole point of the
// function: a limit set on any other connection would be decorative.
func TestCapConnSetsTheLimitOnTheConnectionItReturns(t *testing.T) {
	db := openCapFixture(t)
	conn, err := CapConn(context.Background(), db)
	if err != nil {
		t.Fatalf("CapConn: %v", err)
	}
	defer conn.Close() //nolint:errcheck // test connection

	// newVal < 0 reads the current limit without changing it.
	got, err := sqlite.Limit(conn, sqlite3.SQLITE_LIMIT_LENGTH, -1)
	if err != nil {
		t.Fatalf("reading SQLITE_LIMIT_LENGTH back: %v", err)
	}
	if got != MaxCellBytes {
		t.Fatalf("SQLITE_LIMIT_LENGTH = %d, want %d", got, MaxCellBytes)
	}
}

// TestCapConnRefusesAtTheBoundary pins the cap where the constant says it is.
func TestCapConnRefusesAtTheBoundary(t *testing.T) {
	db := openCapFixture(t)
	conn, err := CapConn(context.Background(), db)
	if err != nil {
		t.Fatalf("CapConn: %v", err)
	}
	defer conn.Close() //nolint:errcheck // test connection

	var n int
	if err := conn.QueryRowContext(context.Background(),
		fmt.Sprintf(`SELECT length(zeroblob(%d))`, MaxCellBytes-16)).Scan(&n); err != nil {
		t.Fatalf("a value just under the cap was refused: %v", err)
	}
	if n != MaxCellBytes-16 {
		t.Fatalf("under-cap length = %d, want %d", n, MaxCellBytes-16)
	}

	err = conn.QueryRowContext(context.Background(),
		fmt.Sprintf(`SELECT length(zeroblob(%d))`, MaxCellBytes+16)).Scan(&n)
	if err == nil {
		t.Fatal("a value just over the cap was accepted")
	}
	if !IsValueTooBig(err) {
		t.Fatalf("over-cap refusal is not SQLITE_TOOBIG: %v", err)
	}
}

// TestIsValueTooBigTestsTheCodeNotTheText: a text match would also claim an
// unrelated error whose SQL happens to quote the phrase.
func TestIsValueTooBigTestsTheCodeNotTheText(t *testing.T) {
	if IsValueTooBig(nil) {
		t.Fatal("a nil error was reported as too big")
	}
	if IsValueTooBig(errors.New("string or blob too big")) {
		t.Fatal("a plain error whose text quotes the phrase was reported as too big")
	}
	wrapped := fmt.Errorf("scanning row: %w", &sqlite.Error{})
	if IsValueTooBig(wrapped) {
		t.Fatalf("an unrelated sqlite error was reported as too big")
	}

	db := openCapFixture(t)
	conn, err := CapConn(context.Background(), db)
	if err != nil {
		t.Fatalf("CapConn: %v", err)
	}
	defer conn.Close() //nolint:errcheck // test connection
	var n int
	err = conn.QueryRowContext(context.Background(),
		fmt.Sprintf(`SELECT length(zeroblob(%d))`, MaxCellBytes+16)).Scan(&n)
	if !IsValueTooBig(err) {
		t.Fatalf("a real SQLITE_TOOBIG was not recognised: %v", err)
	}
	// The same error wrapped the way a caller reports it is still recognised.
	if !IsValueTooBig(fmt.Errorf("query failed: %w", err)) {
		t.Fatalf("a wrapped SQLITE_TOOBIG was not recognised: %v", err)
	}
}

// TestMaxCellBytesClearsTheLargestArchivedRow is why the cap is 4 MiB and not
// something near the 60 000-byte result budget: the limit also refuses a read
// that merely touches a stored value above it.
func TestMaxCellBytesClearsTheLargestArchivedRow(t *testing.T) {
	const largestMeasuredRow = 145795
	if MaxCellBytes <= largestMeasuredRow {
		t.Fatalf("MaxCellBytes = %d does not clear the largest archived row (%d bytes)", MaxCellBytes, largestMeasuredRow)
	}

	db := openCapFixture(t)
	if _, err := db.Exec(`CREATE TABLE resources (id TEXT, data TEXT)`); err != nil {
		t.Fatalf("creating fixture table: %v", err)
	}
	if _, err := db.Exec(`INSERT INTO resources VALUES ('2026-02-01', ?)`,
		`{"note":"`+strings.Repeat("a", 200*1024)+`"}`); err != nil {
		t.Fatalf("seeding a 200 KB row: %v", err)
	}

	conn, err := CapConn(context.Background(), db)
	if err != nil {
		t.Fatalf("CapConn: %v", err)
	}
	defer conn.Close() //nolint:errcheck // test connection

	var n int
	if err := conn.QueryRowContext(context.Background(),
		`SELECT length(json_extract(data,'$.note')) FROM resources`).Scan(&n); err != nil {
		t.Fatalf("json_extract over a 200 KB stored row was refused: %v", err)
	}
	if n != 200*1024 {
		t.Fatalf("json_extract length = %d, want %d", n, 200*1024)
	}
}
